import { forbidden } from 'next/navigation';
import { verifyAdmin } from '../lib/auth';

export default async function AdminPage() {
  const { isAdmin, session } = await verifyAdmin();

  if (!isAdmin) {
    forbidden();
  }

  return (
    <main style={{ padding: '2rem', maxWidth: '1200px', margin: '0 auto' }}>
      <h1 style={{ marginBottom: '1.5rem' }}>Admin Dashboard</h1>
      <p>Welcome, {session?.name}! You have admin access.</p>
    </main>
  );
}

import Link from 'next/link';

export default function ForbiddenPage() {
  return (
    <main
      style={{
        minHeight: '100vh',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        padding: '2rem',
        textAlign: 'center',
      }}
    >
      <h1 style={{ fontSize: '6rem', margin: '0', color: '#ef4444' }}>403</h1>
      <h2 style={{ fontSize: '1.5rem', marginTop: '1rem', color: '#374151' }}>
        Access Forbidden
      </h2>
      <p style={{ maxWidth: '500px', color: '#6b7280', marginTop: '0.5rem' }}>
        You don&apos;t have permission to access this page. This area is
        restricted to administrators only.
      </p>
      <Link
        href="/"
        style={{
          marginTop: '2rem',
          padding: '0.75rem 1.5rem',
          backgroundColor: '#3b82f6',
          color: 'white',
          textDecoration: 'none',
          borderRadius: '0.375rem',
          transition: 'background-color 0.2s',
        }}
      >
        Return to Home
      </Link>
    </main>
  );
}
